// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.27;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ICertificateRegistry} from "./interfaces/ICertificateRegistry.sol";
import {Roles} from "./libraries/Roles.sol";

/// @title CertificateRegistry
/// @notice Soulbound (non-transferable) ERC-721 certificates issued to
///         participants who complete a CeloHT education module. Certificates
///         cannot be sold or transferred — they exist purely as a portable,
///         verifiable record of completed learning, not as a collectible
///         or financial asset.
contract CertificateRegistry is ICertificateRegistry, ERC721, AccessControl, Pausable {
    uint256 private _nextTokenId = 1;

    mapping(uint256 => string) private _courseIdOf;
    mapping(address => uint256[]) private _certificatesOf;
    mapping(uint256 => bool) private _revoked;
    mapping(uint256 => string) private _tokenURIs;

    constructor(address admin) ERC721("CeloHT Certificate", "CELOHT-CERT") {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(Roles.ADMIN_ROLE, admin);
        _grantRole(Roles.ISSUER_ROLE, admin);
    }

    /// @inheritdoc ICertificateRegistry
    function issueCertificate(
        address recipient,
        string calldata courseId,
        string calldata tokenURI_
    ) external onlyRole(Roles.ISSUER_ROLE) whenNotPaused returns (uint256 tokenId) {
        require(recipient != address(0), "CertificateRegistry: zero recipient");
        require(bytes(courseId).length > 0, "CertificateRegistry: empty courseId");

        tokenId = _nextTokenId++;
        _safeMint(recipient, tokenId);
        _courseIdOf[tokenId] = courseId;
        _tokenURIs[tokenId] = tokenURI_;
        _certificatesOf[recipient].push(tokenId);

        emit CertificateIssued(tokenId, recipient, courseId, tokenURI_);
    }

    /// @inheritdoc ICertificateRegistry
    function revokeCertificate(
        uint256 tokenId,
        string calldata reason
    ) external onlyRole(Roles.ISSUER_ROLE) {
        require(_ownerOf(tokenId) != address(0), "CertificateRegistry: nonexistent token");
        require(!_revoked[tokenId], "CertificateRegistry: already revoked");
        _revoked[tokenId] = true;
        emit CertificateRevoked(tokenId, reason);
    }

    /// @inheritdoc ICertificateRegistry
    function certificatesOf(address recipient) external view returns (uint256[] memory) {
        return _certificatesOf[recipient];
    }

    /// @inheritdoc ICertificateRegistry
    function courseIdOf(uint256 tokenId) external view returns (string memory) {
        require(_ownerOf(tokenId) != address(0), "CertificateRegistry: nonexistent token");
        return _courseIdOf[tokenId];
    }

    function isRevoked(uint256 tokenId) external view returns (bool) {
        return _revoked[tokenId];
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        return _tokenURIs[tokenId];
    }

    /// @dev Soulbound enforcement: block every transfer except minting
    ///      (`from == address(0)`) and burning (`to == address(0)`).
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override whenNotPaused returns (address) {
        address from = _ownerOf(tokenId);
        if (from != address(0) && to != address(0)) {
            revert("CertificateRegistry: certificates are non-transferable");
        }
        return super._update(to, tokenId, auth);
    }

    function pause() external onlyRole(Roles.ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(Roles.ADMIN_ROLE) {
        _unpause();
    }

    function supportsInterface(
        bytes4 interfaceId
    ) public view override(ERC721, AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

contracts/DonationManager.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.27;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IDonationManager} from "./interfaces/IDonationManager.sol";
import {Roles} from "./libraries/Roles.sol";
import {BasisPoints} from "./libraries/BasisPoints.sol";

/// @title DonationManager
/// @notice Accepts ERC-20 donations (in practice, cUSD on Celo) earmarked
///         to a specific CeloHT project — most commonly a reforestation
///         campaign — and lets an approved withdrawer route funds to that
///         project's beneficiary. This contract does not create, hold, or
///         distribute any token of its own; it only custodies an existing
///         ERC-20 (the donation asset) on behalf of registered projects.
/// @dev The platform fee defaults to 0 and is hard-capped at 5% (500 bps)
///      in code — it can only be raised by an ADMIN_ROLE holder, and only
///      up to that cap, so a compromised or malicious admin key cannot
///      redirect more than 5% of any donation.
contract DonationManager is IDonationManager, AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using BasisPoints for uint256;

    uint256 public constant MAX_PLATFORM_FEE_BPS = 500; // hard cap: 5%

    IERC20 public immutable donationToken;
    address public feeRecipient;
    uint256 public platformFeeBps;

    mapping(bytes32 => bool) public projectExists;
    mapping(bytes32 => uint256) private _totalDonatedTo;
    mapping(bytes32 => uint256) private _availableBalance;
    mapping(address => uint256) private _totalDonatedBy;

    constructor(address admin, address donationToken_, address feeRecipient_) {
        require(donationToken_ != address(0), "DonationManager: zero token");
        require(feeRecipient_ != address(0), "DonationManager: zero fee recipient");

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(Roles.ADMIN_ROLE, admin);
        _grantRole(Roles.WITHDRAWER_ROLE, admin);

        donationToken = IERC20(donationToken_);
        feeRecipient = feeRecipient_;
    }

    /// @inheritdoc IDonationManager
    function registerProject(
        bytes32 projectId,
        string calldata metadataURI
    ) external onlyRole(Roles.ADMIN_ROLE) {
        require(!projectExists[projectId], "DonationManager: project exists");
        projectExists[projectId] = true;
        emit ProjectRegistered(projectId, metadataURI);
    }

    /// @inheritdoc IDonationManager
    function donate(
        bytes32 projectId,
        uint256 amount,
        string calldata memoURI
    ) external whenNotPaused nonReentrant {
        require(projectExists[projectId], "DonationManager: unknown project");
        require(amount > 0, "DonationManager: zero amount");

        donationToken.safeTransferFrom(msg.sender, address(this), amount);

        uint256 fee = amount.applyBps(platformFeeBps);
        uint256 net = amount - fee;

        _availableBalance[projectId] += net;
        _totalDonatedTo[projectId] += amount;
        _totalDonatedBy[msg.sender] += amount;

        if (fee > 0) {
            donationToken.safeTransfer(feeRecipient, fee);
        }

        emit Donated(msg.sender, projectId, amount, fee, memoURI);
    }

    /// @inheritdoc IDonationManager
    function withdraw(
        bytes32 projectId,
        address to,
        uint256 amount
    ) external onlyRole(Roles.WITHDRAWER_ROLE) whenNotPaused nonReentrant {
        require(to != address(0), "DonationManager: zero recipient");
        require(
            amount > 0 && amount <= _availableBalance[projectId],
            "DonationManager: insufficient balance"
        );

        _availableBalance[projectId] -= amount;
        donationToken.safeTransfer(to, amount);

        emit Withdrawn(projectId, to, amount);
    }

    function setPlatformFeeBps(uint256 newBps) external onlyRole(Roles.ADMIN_ROLE) {
        require(newBps <= MAX_PLATFORM_FEE_BPS, "DonationManager: exceeds fee cap");
        emit PlatformFeeUpdated(platformFeeBps, newBps);
        platformFeeBps = newBps;
    }

    function setFeeRecipient(address newRecipient) external onlyRole(Roles.ADMIN_ROLE) {
        require(newRecipient != address(0), "DonationManager: zero fee recipient");
        feeRecipient = newRecipient;
    }

    /// @inheritdoc IDonationManager
    function totalDonatedTo(bytes32 projectId) external view returns (uint256) {
        return _totalDonatedTo[projectId];
    }

    /// @inheritdoc IDonationManager
    function totalDonatedBy(address donor) external view returns (uint256) {
        return _totalDonatedBy[donor];
    }

    /// @inheritdoc IDonationManager
    function availableBalance(bytes32 projectId) external view returns (uint256) {
        return _availableBalance[projectId];
    }

    function pause() external onlyRole(Roles.ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(Roles.ADMIN_ROLE) {
        _unpause();
    }
}

contracts/GovernanceVoting.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.27;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {Roles} from "./libraries/Roles.sol";

/// @title GovernanceVoting
/// @notice A deliberately simple, role-gated proposal-and-vote system.
///         CeloHT has no governance token: voting weight is one address,
///         one vote, and only addresses granted VOTER_ROLE (e.g. approved
///         community agents or verified contributors, at the Maintainer
///         Council's discretion) may vote. This trades permissionless
///         participation for resistance to plutocratic and Sybil attacks
///         that a token-weighted or fully open model would be exposed to
///         — see docs/governance.md for the tradeoffs and the intended
///         path toward broader participation over time.
contract GovernanceVoting is AccessControl, Pausable {
    enum ProposalState {
        Active,
        Closed
    }

    struct Proposal {
        address proposer;
        string metadataURI; // title, description, discussion link
        uint64 startTime;
        uint64 endTime;
        uint256 votesFor;
        uint256 votesAgainst;
        ProposalState state;
    }

    Proposal[] private _proposals;
    mapping(uint256 => mapping(address => bool)) private _hasVoted;

    event ProposalCreated(
        uint256 indexed proposalId,
        address indexed proposer,
        string metadataURI,
        uint64 startTime,
        uint64 endTime
    );
    event VoteCast(uint256 indexed proposalId, address indexed voter, bool support);
    event ProposalClosed(uint256 indexed proposalId, uint256 votesFor, uint256 votesAgainst);

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(Roles.ADMIN_ROLE, admin);
        _grantRole(Roles.PROPOSER_ROLE, admin);
        _grantRole(Roles.VOTER_ROLE, admin);
    }

    function createProposal(
        string calldata metadataURI,
        uint64 votingPeriodSeconds
    ) external onlyRole(Roles.PROPOSER_ROLE) whenNotPaused returns (uint256 proposalId) {
        require(bytes(metadataURI).length > 0, "GovernanceVoting: empty metadata");
        require(votingPeriodSeconds >= 1 days, "GovernanceVoting: period too short");

        proposalId = _proposals.length;
        uint64 startTime = uint64(block.timestamp);
        uint64 endTime = startTime + votingPeriodSeconds;

        _proposals.push(
            Proposal({
                proposer: msg.sender,
                metadataURI: metadataURI,
                startTime: startTime,
                endTime: endTime,
                votesFor: 0,
                votesAgainst: 0,
                state: ProposalState.Active
            })
        );

        emit ProposalCreated(proposalId, msg.sender, metadataURI, startTime, endTime);
    }

    function castVote(
        uint256 proposalId,
        bool support
    ) external onlyRole(Roles.VOTER_ROLE) whenNotPaused {
        Proposal storage proposal = _getProposal(proposalId);
        require(proposal.state == ProposalState.Active, "GovernanceVoting: not active");
        require(block.timestamp <= proposal.endTime, "GovernanceVoting: voting ended");
        require(!_hasVoted[proposalId][msg.sender], "GovernanceVoting: already voted");

        _hasVoted[proposalId][msg.sender] = true;
        if (support) {
            proposal.votesFor += 1;
        } else {
            proposal.votesAgainst += 1;
        }

        emit VoteCast(proposalId, msg.sender, support);
    }

    /// @notice Closes a proposal after its voting period ends. Anyone may
    ///         call this — it only finalizes state, it cannot change the
    ///         vote tally.
    function closeProposal(uint256 proposalId) external {
        Proposal storage proposal = _getProposal(proposalId);
        require(proposal.state == ProposalState.Active, "GovernanceVoting: already closed");
        require(block.timestamp > proposal.endTime, "GovernanceVoting: voting still open");

        proposal.state = ProposalState.Closed;
        emit ProposalClosed(proposalId, proposal.votesFor, proposal.votesAgainst);
    }

    function getProposal(uint256 proposalId) external view returns (Proposal memory) {
        return _getProposal(proposalId);
    }

    function proposalCount() external view returns (uint256) {
        return _proposals.length;
    }

    function hasVoted(uint256 proposalId, address voter) external view returns (bool) {
        return _hasVoted[proposalId][voter];
    }

    function _getProposal(uint256 proposalId) private view returns (Proposal storage) {
        require(proposalId < _proposals.length, "GovernanceVoting: invalid proposalId");
        return _proposals[proposalId];
    }

    function pause() external onlyRole(Roles.ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(Roles.ADMIN_ROLE) {
        _unpause();
    }
}

contracts/ImpactRegistry.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.27;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {IImpactRegistry} from "./interfaces/IImpactRegistry.sol";
import {Roles} from "./libraries/Roles.sol";

/// @title ImpactRegistry
/// @notice Records verified tree-planting activity for CeloHT reforestation
///         projects. Only accounts holding VERIFIER_ROLE may log a planting
///         record, keeping the on-chain count tied to activity that has
///         actually been reviewed (e.g. against submitted photo and
///         geolocation evidence pinned to IPFS), rather than self-reported
///         numbers.
contract ImpactRegistry is IImpactRegistry, AccessControl, Pausable {
    mapping(bytes32 => bool) public projectExists;
    mapping(bytes32 => uint256) private _totalTreesFor;

    PlantingRecord[] private _records;

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(Roles.ADMIN_ROLE, admin);
        _grantRole(Roles.VERIFIER_ROLE, admin);
    }

    /// @inheritdoc IImpactRegistry
    function createProject(
        bytes32 projectId,
        string calldata metadataURI
    ) external onlyRole(Roles.ADMIN_ROLE) {
        require(!projectExists[projectId], "ImpactRegistry: project exists");
        projectExists[projectId] = true;
        emit ProjectCreated(projectId, metadataURI);
    }

    /// @inheritdoc IImpactRegistry
    function recordPlanting(
        bytes32 projectId,
        uint32 treeCount,
        string calldata evidenceURI
    ) external onlyRole(Roles.VERIFIER_ROLE) whenNotPaused returns (uint256 recordId) {
        require(projectExists[projectId], "ImpactRegistry: unknown project");
        require(treeCount > 0, "ImpactRegistry: zero trees");
        require(bytes(evidenceURI).length > 0, "ImpactRegistry: missing evidence");

        recordId = _records.length;
        _records.push(
            PlantingRecord({
                projectId: projectId,
                reportedBy: msg.sender,
                treeCount: treeCount,
                evidenceURI: evidenceURI,
                recordedAt: uint64(block.timestamp)
            })
        );

        _totalTreesFor[projectId] += treeCount;

        emit PlantingRecorded(projectId, recordId, msg.sender, treeCount);
    }

    /// @inheritdoc IImpactRegistry
    function totalTreesFor(bytes32 projectId) external view returns (uint256) {
        return _totalTreesFor[projectId];
    }

    /// @inheritdoc IImpactRegistry
    function recordCount() external view returns (uint256) {
        return _records.length;
    }

    /// @inheritdoc IImpactRegistry
    function getRecord(uint256 recordId) external view returns (PlantingRecord memory) {
        require(recordId < _records.length, "ImpactRegistry: invalid recordId");
        return _records[recordId];
    }

    function pause() external onlyRole(Roles.ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(Roles.ADMIN_ROLE) {
        _unpause();
    }
}

