// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.27;

/// @title IImpactRegistry
/// @notice Interface for recording verified reforestation activity.
interface IImpactRegistry {
    struct PlantingRecord {
        bytes32 projectId;
        address reportedBy;
        uint32 treeCount;
        string evidenceURI; // IPFS URI: photos + geolocation metadata
        uint64 recordedAt;
    }

    event ProjectCreated(bytes32 indexed projectId, string metadataURI);
    event PlantingRecorded(
        bytes32 indexed projectId,
        uint256 indexed recordId,
        address indexed reportedBy,
        uint32 treeCount
    );

    function createProject(bytes32 projectId, string calldata metadataURI) external;

    function recordPlanting(
        bytes32 projectId,
        uint32 treeCount,
        string calldata evidenceURI
    ) external returns (uint256 recordId);

    function totalTreesFor(bytes32 projectId) external view returns (uint256);

    function recordCount() external view returns (uint256);

    function getRecord(uint256 recordId) external view returns (PlantingRecord memory);
}

contracts/libraries/BasisPoints.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.27;

/// @title BasisPoints
/// @notice Minimal fixed-point helper for basis-point (1/100th of a
///         percent) calculations, used by DonationManager to compute an
///         optional, capped platform fee.
library BasisPoints {
    uint256 internal constant MAX_BPS = 10_000; // 100.00%

    error BasisPointsOverflow(uint256 value);

    /// @notice Returns `amount * bps / 10_000`, rounded down.
    function applyBps(uint256 amount, uint256 bps) internal pure returns (uint256) {
        if (bps > MAX_BPS) revert BasisPointsOverflow(bps);
        return (amount * bps) / MAX_BPS;
    }
}

contracts/libraries/Roles.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.27;

/// @title Roles
/// @notice Shared AccessControl role identifiers used across the CeloHT
///         contract suite, so the same role (e.g. an operations admin)
///         resolves to the same identifier in every contract.
/// @dev None of these roles are, or grant control over, a token. CeloHT
///      does not issue a token; these roles gate administrative and
///      verification actions on registries and the donation manager only.
library Roles {
    /// @notice Can pause/unpause a contract and manage other roles.
    bytes32 internal constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    /// @notice Can approve, suspend, or reinstate community agents.
    bytes32 internal constant COORDINATOR_ROLE = keccak256("COORDINATOR_ROLE");

    /// @notice Can issue learning certificates to participants.
    bytes32 internal constant ISSUER_ROLE = keccak256("ISSUER_ROLE");

    /// @notice Can record verified reforestation activity.
    bytes32 internal constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");

    /// @notice Can withdraw donated funds to an approved beneficiary.
    bytes32 internal constant WITHDRAWER_ROLE = keccak256("WITHDRAWER_ROLE");

    /// @notice Can create governance proposals.
    bytes32 internal constant PROPOSER_ROLE = keccak256("PROPOSER_ROLE");

    /// @notice Can cast votes on governance proposals.
    bytes32 internal constant VOTER_ROLE = keccak256("VOTER_ROLE");
}

